{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "cycle-phased-strength-12wk",
    "name": "12-Week Cycle-Phased Strength Programme",
    "description": "A 12-week progressive strength programme for a 28-year-old recreational lifter with severe primary dysmenorrhea. Training intensity and modality are phased around a 28-day menstrual cycle. Flow days (cycle days 1–3) are restricted to gentle recovery and low-intensity movement only — no high-intensity work, no heavy Valsalva lifting, no jumping. The remaining three cycle phases (follicular, ovulatory, luteal) are programmed to leverage hormonal milieu for progressive overload, peak performance, and volume management respectively.",
    "type": "workout",
    "visibility": "template",
    "metadata": {
      "created_at": "2026-06-01T00:00:00Z",
      "updated_at": "2026-06-01T00:00:00Z",
      "created_by": "personal-trainer",
      "tags": [
        "strength",
        "cycle-phasing",
        "dysmenorrhea",
        "female-athlete",
        "periodization",
        "12-week"
      ],
      "difficulty": "intermediate",
      "estimated_duration_days": 84,
      "language": "en"
    },
    "goals": [
      {
        "id": "goal-strength",
        "type": "primary",
        "category": "strength",
        "name": "Progressive Strength Development",
        "description": "Build lower and upper body compound strength across the 12-week programme, peaking during follicular and ovulatory phases.",
        "target": {
          "metric": "compound_lift_load",
          "target_value": 15,
          "unit": "percent_increase",
          "measurement_type": "relative"
        },
        "milestones": [
          {
            "id": "ms-4wk",
            "name": "4-Week Strength Check",
            "target_value": 5,
            "reward_points": 50
          },
          {
            "id": "ms-8wk",
            "name": "8-Week Strength Check",
            "target_value": 10,
            "reward_points": 100
          },
          {
            "id": "ms-12wk",
            "name": "12-Week Final Assessment",
            "target_value": 15,
            "reward_points": 200
          }
        ]
      },
      {
        "id": "goal-wellbeing",
        "type": "secondary",
        "category": "wellbeing",
        "name": "Symptom-Aware Training Consistency",
        "description": "Maintain training consistency across all cycle phases without exacerbating dysmenorrhea symptoms on flow days.",
        "target": {
          "metric": "training_sessions_completed",
          "target_value": 36,
          "unit": "sessions",
          "measurement_type": "absolute"
        },
        "milestones": [
          {
            "id": "ms-consistency-4wk",
            "name": "First Month Consistency",
            "target_value": 12,
            "reward_points": 40
          }
        ]
      }
    ],
    "requirements": {
      "min_age": 18,
      "max_age": 45,
      "fitness_level": ["recreational", "intermediate"],
      "equipment": [
        {
          "id": "barbell",
          "name": "Barbell",
          "required": true
        },
        {
          "id": "squat-rack",
          "name": "Squat Rack / Power Rack",
          "required": true
        },
        {
          "id": "dumbbells",
          "name": "Dumbbells (adjustable or set)",
          "required": true
        },
        {
          "id": "bench",
          "name": "Adjustable Bench",
          "required": true
        },
        {
          "id": "cable-machine",
          "name": "Cable Machine",
          "required": false,
          "alternatives": ["resistance-bands"]
        },
        {
          "id": "resistance-bands",
          "name": "Resistance Bands",
          "required": false,
          "alternatives": ["cable-machine"]
        },
        {
          "id": "foam-roller",
          "name": "Foam Roller",
          "required": false
        }
      ],
      "contraindications": [
        {
          "condition": "icd10:N94.4",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": [
            "any-high-intensity-cardio",
            "any-heavy-valsalva-lift",
            "any-plyometric"
          ]
        },
        {
          "condition": "primary_dysmenorrhea_flow_days_1_3",
          "severity": "moderate",
          "action": "exclude",
          "affected_activities": [
            "barbell-back-squat-heavy",
            "barbell-deadlift-heavy",
            "barbell-rdl-heavy",
            "box-jump",
            "jump-squat",
            "hiit-cardio"
          ]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 4,
        "min_minutes_per_day": 45,
        "max_minutes_per_day": 75
      }
    },
    "personalization": {
      "inputs": [
        {
          "id": "cycle-day",
          "type": "number",
          "source": "user.cycle_day",
          "label": "Current cycle day (1–28)"
        },
        {
          "id": "session-rpe-yesterday",
          "type": "number",
          "source": "wellness.session_rpe_yesterday",
          "label": "Yesterday's session RPE"
        },
        {
          "id": "subjective-readiness",
          "type": "number",
          "source": "wellness.subjective_readiness",
          "label": "Today's subjective readiness (1–10)"
        },
        {
          "id": "sleep-hours",
          "type": "number",
          "source": "wellness.sleep_hours_last_night",
          "label": "Sleep hours last night"
        },
        {
          "id": "menstrual-phase",
          "type": "enum",
          "source": "wellness.menstrual_phase",
          "label": "Current menstrual phase",
          "options": ["menstrual", "follicular", "ovulatory", "luteal"]
        }
      ],
      "rules": [
        {
          "id": "rule-flow-day-restrict",
          "condition": {
            "field": "user.cycle_day",
            "op": "lte",
            "value": 3
          },
          "actions": [
            {
              "type": "swap_block",
              "scope": "main",
              "replacement": "gentle-recovery-block"
            },
            {
              "type": "set_intensity_cap",
              "scope": "session",
              "max_rpe": 5
            }
          ]
        },
        {
          "id": "rule-low-readiness",
          "condition": {
            "field": "wellness.subjective_readiness",
            "op": "lte",
            "value": 4
          },
          "actions": [
            {
              "type": "reduce_volume",
              "scope": "session",
              "factor": 0.8
            }
          ]
        },
        {
          "id": "rule-poor-sleep",
          "condition": {
            "field": "wellness.sleep_hours_last_night",
            "op": "lt",
            "value": 6
          },
          "actions": [
            {
              "type": "reduce_intensity",
              "scope": "session",
              "rpe_reduction": 1
            }
          ]
        }
      ]
    },
    "athlete_thresholds": {
      "body_weight_kg": 65
    },
    "progress": {
      "checkpoints": [
        {
          "id": "cp-baseline",
          "name": "Baseline Assessment",
          "at": { "value": 0, "unit": "days" },
          "measurements": [
            { "metric": "body_weight_kg" },
            { "metric": "one_rm_kg", "note": "Estimated 1RM: squat, deadlift, bench press, hip thrust" },
            { "metric": "session_rpe_avg" }
          ],
          "questions": [
            "Rate your average dysmenorrhea pain on flow days (0–10).",
            "Which exercises feel most uncomfortable during your period?"
          ]
        },
        {
          "id": "cp-4wk",
          "name": "4-Week Check-In",
          "at": { "value": 28, "unit": "days" },
          "measurements": [
            { "metric": "body_weight_kg" },
            { "metric": "one_rm_kg", "note": "Re-test estimated 1RM: squat, deadlift, bench press" },
            { "metric": "session_rpe_avg" }
          ],
          "questions": [
            "Has training on flow days felt manageable?",
            "Any increase or decrease in dysmenorrhea symptoms?"
          ]
        },
        {
          "id": "cp-8wk",
          "name": "8-Week Check-In",
          "at": { "value": 56, "unit": "days" },
          "measurements": [
            { "metric": "body_weight_kg" },
            { "metric": "one_rm_kg", "note": "Re-test estimated 1RM: squat, deadlift, bench press, hip thrust" },
            { "metric": "session_rpe_avg" }
          ],
          "questions": [
            "How is energy and motivation tracking across cycle phases?",
            "Any joint discomfort around ovulation (elevated relaxin)?"
          ]
        },
        {
          "id": "cp-12wk",
          "name": "12-Week Final Assessment",
          "at": { "value": 84, "unit": "days" },
          "measurements": [
            { "metric": "body_weight_kg" },
            { "metric": "one_rm_kg", "note": "Final 1RM test: squat, deadlift, bench press, hip thrust" },
            { "metric": "session_rpe_avg" },
            { "metric": "free_text", "note": "Overall programme experience and symptom impact" }
          ],
          "questions": [
            "Did cycle-phased programming improve your training experience?",
            "Which phase felt strongest? Which felt hardest?"
          ]
        }
      ],
      "points_system": {
        "enabled": true,
        "rules": [
          { "action": "complete_training_session", "points": 10 },
          { "action": "complete_flow_day_recovery", "points": 15 },
          { "action": "complete_checkpoint", "points": 50 },
          { "action": "log_readiness_score", "points": 3 }
        ]
      }
    },
    "notifications": [
      {
        "id": "notif-flow-day-reminder",
        "enabled": true,
        "message": "Flow day detected (cycle day 1–3). Today's session has been adjusted to gentle recovery. Listen to your body — rest is valid training.",
        "timing_reference": "session_start",
        "timing_offset": { "value": -30, "unit": "minutes" }
      },
      {
        "id": "notif-ovulatory-peak",
        "enabled": true,
        "message": "You're in your ovulatory window — energy and strength are typically at their peak. Today is a great day to push intensity. Stay mindful of joint laxity.",
        "timing_reference": "session_start",
        "timing_offset": { "value": -15, "unit": "minutes" }
      },
      {
        "id": "notif-luteal-heads-up",
        "enabled": true,
        "message": "Luteal phase: volume is managed and RPE targets are slightly lower. Fatigue and mood shifts are normal — consistency matters more than PRs right now.",
        "timing_reference": "session_start",
        "timing_offset": { "value": -15, "unit": "minutes" }
      }
    ],
    "phases": [
      {
        "id": "phase-1-cycle-1",
        "name": "Phase 1 — Cycle 1 (Weeks 1–4): Foundation & Cycle Familiarisation",
        "order": 1,
        "type": "accumulation",
        "description": "Establish movement quality and baseline loads across all four cycle sub-phases. Flow days (cycle days 1–3) use gentle recovery. Follicular days (4–13) build volume at moderate intensity. Ovulatory days (14–16) introduce heavier loading. Luteal days (17–28) maintain with reduced volume.",
        "duration": { "value": 4, "unit": "weeks" },
        "weeks": [
          {
            "id": "p1-week1",
            "name": "Week 1 — Menstrual + Early Follicular",
            "order": 1,
            "days": [
              {
                "id": "p1w1-d1",
                "day_of_week": 1,
                "type": "active_recovery",
                "name": "Flow Day 1 — Gentle Recovery (Cycle Day 1)",
                "estimated_duration_minutes": 30,
                "blocks": [
                  {
                    "id": "p1w1-d1-b1",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1w1-d1-breathwork",
                        "type": "recovery",
                        "name": "Diaphragmatic Breathwork & Pelvic Floor Release",
                        "category": "breathwork",
                        "prescription": {
                          "duration": { "value": 10, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "diaphragmatic-breath",
                              "type": "recovery_exercise",
                              "name": "Diaphragmatic Breathing",
                              "modality": "breathwork",
                              "reps": 10,
                              "hold_seconds": 4,
                              "body_part": "diaphragm"
                            }
                          ]
                        }
                      },
                      {
                        "id": "p1w1-d1-stretch",
                        "type": "recovery",
                        "name": "Gentle Lower Body Mobility",
                        "category": "mobility",
                        "prescription": {
                          "duration": { "value": 20, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "childs-pose",
                              "type": "recovery_exercise",
                              "name": "Child's Pose",
                              "modality": "static_stretch",
                              "hold_seconds": 60,
                              "reps": 3,
                              "body_part": "lower_back",
                              "intensity_rpe": 3
                            },
                            {
                              "id": "supine-knee-hug",
                              "type": "recovery_exercise",
                              "name": "Supine Knee-to-Chest",
                              "modality": "static_stretch",
                              "hold_seconds": 45,
                              "reps": 3,
                              "sides": "both",
                              "body_part": "glutes",
                              "intensity_rpe": 3
                            },
                            {
                              "id": "cat-cow",
                              "type": "recovery_exercise",
                              "name": "Cat-Cow Mobilisation",
                              "modality": "dynamic_stretch",
                              "reps": 12,
                              "body_part": "spinal_erectors",
                              "intensity_rpe": 2
                            },
                            {
                              "id": "supine-hip-flexor",
                              "type": "recovery_exercise",
                              "name": "Supine Hip Flexor Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 45,
                              "reps": 2,
                              "sides": "both",
                              "body_part": "hip_flexors",
                              "intensity_rpe": 3
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "p1w1-d2",
                "day_of_week": 2,
                "type": "active_recovery",
                "name": "Flow Day 2 — Gentle Recovery (Cycle Day 2)",
                "estimated_duration_minutes": 30,
                "blocks": [
                  {
                    "id": "p1w1-d2-b1",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1w1-d2-walk",
                        "type": "cardio",
                        "name": "Easy Walk",
                        "modality": "walking",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 20, "unit": "minutes" },
                          "intensity": {
                            "type": "rpe",
                            "zone_model": "rpe_borg_10",
                            "target": { "min": 2, "max": 3 }
                          }
                        }
                      },
                      {
                        "id": "p1w1-d2-meditation",
                        "type": "meditation",
                        "name": "Body Scan Meditation",
                        "category": "mindfulness",
                        "prescription": {
                          "duration": { "value": 10, "unit": "minutes" },
                          "guided": true
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "p1w1-d3",
                "day_of_week": 3,
                "type": "active_recovery",
                "name": "Flow Day 3 — Gentle Recovery (Cycle Day 3)",
                "estimated_duration_minutes": 30,
                "blocks": [
                  {
                    "id": "p1w1-d3-b1",
                    "type": "main",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1w1-d3-recovery",
                        "type": "recovery",
                        "name": "Full Body Gentle Stretch & Foam Roll",
                        "category": "mobility",
                        "prescription": {
                          "duration": { "value": 30, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "foam-roll-quads",
                              "type": "recovery_exercise",
                              "name": "Foam Roll Quads",
                              "modality": "smr_foam_roll",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "body_part": "quadriceps",
                              "intensity_rpe": 4
                            },
                            {
                              "id": "foam-roll-glutes",
                              "type": "recovery_exercise",
                              "name": "Foam Roll Glutes",
                              "modality": "smr_foam_roll",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "body_part": "glutes",
                              "intensity_rpe": 4
                            },
                            {
                              "id": "pigeon-pose",
                              "type": "recovery_exercise",
                              "name": "Pigeon Pose Hip Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 60,
                              "reps": 2,
                              "sides": "both",
                              "body_part": "hip_abductors",
                              "intensity_rpe": 4
                            },
                            {
                              "id": "seated-forward-fold",
                              "type": "recovery_exercise",
                              "name": "Seated Forward Fold",
                              "modality": "static_stretch",
                              "hold_seconds": 45,
                              "reps": 3,
                              "body_part": "hamstrings",
                              "intensity_rpe": 3
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "p1w1-d4",
                "day_of_week": 4,
                "type": "training",
                "name": "Follicular Day 1 — Lower Body Foundation (Cycle Day 4)",
                "estimated_duration_minutes": 60,
                "blocks": [
                  {
                    "id": "p1w1-d4-warmup",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "p1w1-d4-wu1",
                        "type": "cardio",
                        "name": "Bike or Treadmill Warm-Up",
                        "modality": "cycling",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 5, "unit": "minutes" },
                          "intensity": {
                            "type": "rpe",
                            "zone_model": "rpe_borg_10",
                            "target": { "min": 3, "max": 4 }
                          }
                        }
                      },
                      {
                        "id": "p1w1-d4-wu2",
                        "type": "recovery",
                        "name": "Dynamic Lower Body Warm-Up",
                        "category": "warmup_mobility",
                        "prescription": {
                          "duration": { "value": 7, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "leg-swing-sagittal",
                              "type": "recovery_exercise",
                              "name": "Leg Swings (Sagittal)",
                              "modality": "dynamic_stretch",
                              "reps": 12,
                              "sides": "both",
                              "body_part": "hip_flexors"
                            },
                            {
                              "id": "bodyweight-squat-warmup",
                              "type": "recovery_exercise",
                              "name": "Bodyweight Squat",
                              "modality": "dynamic_stretch",
                              "reps": 15,
                              "body_part": "quadriceps"
                            },
                            {
                              "id": "glute-bridge-warmup",
                              "type": "recovery_exercise",
                              "name": "Glute Bridge",
                              "modality": "dynamic_stretch",
                              "reps": 15,
                              "body_part": "glutes"
                            }
                          ]
                        }
                      }
                    ]
                  },
                  {
                    "id": "p1w1-d4-main",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "p1w1-d4-squat",
                        "type": "exercise",
                        "exercise_ref": "barbell-back-squat",
                        "name": "Barbell Back Squat",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 8, "max": 10 },
                          "rest": { "value": 2, "unit": "minutes" },
                          "weight": { "type": "percentage_1rm", "value": 65, "metric": "e1RM" }
                        },
                        "target_rpe": 6,
                        "target_rir": 3,
                        "primary_muscles": ["quadriceps", "glutes"],
                        "secondary_muscles": ["hamstrings", "spinal_erectors"],
                        "movement_pattern": "squat"
                      },
                      {
                        "id": "p1w1-d4-rdl",
                        "type": "exercise",
                        "exercise_ref": "barbell-rdl",
                        "name": "Barbell Romanian Deadlift",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "percentage_1rm", "value": 60, "metric": "e1RM" }
                        },
                        "target_rpe": 6,
                        "target_rir": 3,
                        "primary_muscles": ["hamstrings", "glutes"],
                        "secondary_muscles": ["spinal_erectors", "lower_back"],
                        "movement_pattern": "hinge"
                      },
                      {
                        "id": "p1w1-d4-leg-press",
                        "type": "exercise",
                        "exercise_ref": "leg-press",
                        "name": "Leg Press",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "value": 60, "unit": "kg" }
                        },
                        "target_rpe": 6,
                        "primary_muscles": ["quadriceps", "glutes"],
                        "secondary_muscles": ["hamstrings"],
                        "movement_pattern": "squat"
                      },
                      {
                        "id": "p1w1-d4-hip-thrust",
                        "type": "exercise",
                        "exercise_ref": "barbell-hip-thrust",
                        "name": "Barbell Hip Thrust",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "weight": { "type": "absolute", "value": 40, "unit": "kg" }
                        },
                        "target_rpe": 6,
                        "primary_muscles": ["glutes"],
                        "secondary_muscles": ["hamstrings"],
                        "movement_pattern": "hinge"
                      },
                      {
                        "id": "p1w1-d4-calf-raise",
                        "type": "exercise",
                        "exercise_ref": "standing-calf-raise",
                        "name": "Standing Calf Raise",
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 3,
                          "reps": { "min": 12, "max": 15 },
                          "rest": { "value": 60, "unit": "seconds" },
                          "weight": { "type": "bodyweight" }
                        },
                        "target_rpe": 6,
                        "primary_muscles": ["calves"],
                        "movement_pattern": "isolation"
                      }
                    ]
                  },
                  {
                    "id": "p1w1-d4-cooldown",
                    "type": "cooldown",
                    "order": 3,
                    "activities": [
                      {
                        "id": "p1w1-d4-cd1",
                        "type": "recovery",
                        "name": "Lower Body Cooldown Stretch",
                        "category": "flexibility",
                        "prescription": {
                          "duration": { "value": 8, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "quad-stretch-cd",
                              "type": "recovery_exercise",
                              "name": "Standing Quad Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "body_part": "quadriceps",
                              "intensity_rpe": 5
                            },
                            {
                              "id": "hamstring-stretch-cd",
                              "type": "recovery_exercise",
                              "name": "Seated Hamstring Stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "reps": 2,
                              "sides": "both",
                              "body_part": "hamstrings",
                              "intensity_rpe": 5
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "p1w1-d5",
